<?php
require '../config.php';require '../includes/functions.php';require_admin();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['delete_id'])){$stmt=$pdo->prepare('DELETE FROM products WHERE id=?');$stmt->execute([(int)$_POST['delete_id']]);$_SESSION['flash']='Product deleted.';redirect('admin/products.php');}
 $name=trim($_POST['name']??'');$slug=strtolower(trim($_POST['slug']??''));$slug=preg_replace('/[^a-z0-9-]+/','-', $slug);$desc=trim($_POST['description']??'');$category=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??0);$image=trim($_POST['image_url']??'');
 if(!$name||!preg_match('/^[a-z0-9-]+$/',$slug)||!$desc||$category<1||$price<=0||$stock<0)$error='Check all fields; slug must use lowercase letters, numbers and hyphens.';
 else{try{$stmt=$pdo->prepare('INSERT INTO products(category_id,name,slug,description,price,image_url,stock,featured) VALUES(?,?,?,?,?,?,?,?)');$stmt->execute([$category,$name,$slug,$desc,$price,$image,$stock,isset($_POST['featured'])?1:0]);$_SESSION['flash']='Product added.';redirect('admin/products.php');}catch(PDOException $e){$error='Could not add product. The slug may already exist.';}}
}
$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$products=$pdo->query('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();$pageTitle='Manage products';require '../includes/header.php';
?>
<div class="page-title"><span class="eyebrow">Store administration</span><h1>Manage products</h1><p>Add new products or remove existing ones.</p></div>
<?php if($error): ?><div class="error"><?= e($error) ?></div><?php endif; ?>
<div class="form-card" style="max-width:none;margin-bottom:35px"><h2>Add a product</h2><form method="post"><div class="field"><label>Name</label><input name="name" required maxlength="180"></div><div class="field"><label>URL slug (unique)</label><input name="slug" required placeholder="linen-kitchen-towel"></div><div class="field"><label>Category</label><select name="category_id" required><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Description</label><textarea name="description" required></textarea></div><div class="field"><label>Price (₹)</label><input name="price" type="number" min=".01" step=".01" required></div><div class="field"><label>Stock</label><input name="stock" type="number" min="0" required value="0"></div><div class="field"><label>Image URL</label><input name="image_url" type="url" placeholder="https://..."></div><div class="field"><label><input name="featured" type="checkbox" value="1"> Feature on homepage</label></div><button class="btn">Add product</button></form></div>
<div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Action</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['category_name']) ?></td><td><?= money($p['price']) ?></td><td><?= (int)$p['stock'] ?></td><td><form method="post" data-confirm="Delete this product?" class="inline-form"><button class="text-link" name="delete_id" value="<?= (int)$p['id'] ?>">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div>
<?php require '../includes/footer.php'; ?>
